import React,{useEffect,useMemo,useRef,useState}from 'react';
import './App.css';
import './light-theme.css';
import {roadmap,topicInfo,problems,leaders} from './data/content';
import {RippleGrid} from './components/ui/ripple-grid';
import FluidFlowGrid from './components/ui/fluid-flow-grid';

const nav=[['Home','/'],['Roadmap','/roadmap'],['Learn','/learn/arrays'],['Events','/events'],['Leaderboard','/leaderboard']];
const go=(to)=>{window.history.pushState({},'',to);window.dispatchEvent(new PopStateEvent('popstate'))};
function Button({children,onClick,kind=''}){return <button className={'btn '+kind} onClick={onClick}>{children}<span>→</span></button>}
function Progress({value}){return <div className="progress"><i style={{width:value+'%'}}/></div>}
function Navbar({openSearch}){const [path,setPath]=useState(location.pathname),[open,setOpen]=useState(false);useEffect(()=>{const f=()=>setPath(location.pathname);addEventListener('popstate',f);return()=>removeEventListener('popstate',f)},[]);return <header><RippleGrid className="header-ripple-grid" size={8} cellSize={12} filledCells={[{row:1,col:2},{row:3,col:5},{row:6,col:6}]} cellColor="rgba(255,255,255,.18)" filledCellColor="rgba(21,151,220,.2)" borderColor="rgba(49,159,208,.16)"/><a className="brand club-logo" href="/" onClick={e=>{e.preventDefault();go('/')}}><b>ACM</b><span>BV</span><em>CHAPTER</em></a><nav className={open?'shown':''}>{nav.map(([n,p])=><a key={p} className={path===p?'active':''} onClick={()=>{go(p);setOpen(false)}}>{n}</a>)}</nav><div className="nav-right"><button className="search-small" onClick={openSearch}>⌕ <span>Search</span><kbd>⌘ K</kbd></button><a onClick={()=>go('/progress')} className={path==='/progress'?'active':''}>Progress</a><Button onClick={()=>go('/register')}>Join ACM BV</Button><button className="avatar">PJ</button></div><button className="hamburger" onClick={()=>setOpen(!open)} aria-label="Menu">{open?'×':'☰'}</button></header>}
function OrbitalNavigation({onClose}){const nodes=[['HOME','Home','/', 'Meet the ACM BV community'],['MAP','Roadmap','/roadmap','Choose your learning path'],['LEARN','Learn','/learn/arrays','Explore interactive lessons'],['LAB','Practice','/practice','Build problem-solving fluency'],['EVENTS','Events','/events','Meet the ACM BV community'],['RANK','Leaderboard','/leaderboard','See community progress'],['ME','Progress','/progress','Track your own growth']];const [active,setActive]=useState(nodes.findIndex(n=>location.pathname===n[2]||location.pathname.startsWith('/learn/')&&n[1]==='Learn'));const stageRef=useRef(null);const handleMove=e=>{const box=stageRef.current?.getBoundingClientRect();if(!box)return;stageRef.current.style.setProperty('--tilt-x',`${((e.clientY-box.top)/box.height-.5)*-7}deg`);stageRef.current.style.setProperty('--tilt-y',`${((e.clientX-box.left)/box.width-.5)*8}deg`)};const selected=nodes[active<0?0:active];return <div className="orbit-menu" role="dialog" aria-modal="true" aria-label="Site navigation" onClick={onClose}><div className="orbit-menu-panel" onClick={e=>e.stopPropagation()}><div className="orbit-menu-top"><div><p className="eyebrow">ACM BV / SITE MAP</p><h2>FIND YOUR<br/>NEXT NODE.</h2></div><button className="orbit-close" onClick={onClose} aria-label="Close navigation">×</button></div><div className="navigation-stage" ref={stageRef} onMouseMove={handleMove} onMouseLeave={()=>{stageRef.current?.style.setProperty('--tilt-x','0deg');stageRef.current?.style.setProperty('--tilt-y','0deg')}}><div className="nav-orbit nav-orbit-one"/><div className="nav-orbit nav-orbit-two"/><div className="nav-core"><b>ACM</b><span>BV</span><small>COMMUNITY</small></div>{nodes.map(([code,title,path,detail],i)=>{const angle=(i*360/nodes.length-90)*Math.PI/180;return <button key={title} className={'nav-node '+(active===i?'active':'')} style={{'--x':`${50+41*Math.cos(angle)}%`,'--y':`${50+33*Math.sin(angle)}%`,'--delay':`${i*-0.55}s`}} onMouseEnter={()=>setActive(i)} onFocus={()=>setActive(i)} onClick={()=>{go(path);onClose()}}><i>{code}</i><b>{title}</b></button>})}</div><div className="orbit-menu-detail"><span className="mono">{selected[0]} / 0{active+1}</span><p>{selected[3]}</p><button onClick={()=>{go(selected[2]);onClose()}}>Open {selected[1]} <span>→</span></button></div><p className="orbit-tip">Move your cursor across the orbit · Select any node to navigate</p></div></div>}
function Footer(){return <footer><div><div className="brand"><b>ACM</b><span>BV</span><em>CHAPTER</em></div><p>Connect. Create. Contribute.</p><small>An initiative by ACM Student Chapter<br/>Banasthali Vidyapith</small></div><div className="footer-links">{nav.map(([n,p])=><a key={p} onClick={()=>go(p)}>{n}</a>)}<a href="https://acm-bv.acm.org/" target="_blank" rel="noreferrer">ACM BV ↗</a></div><small>© 2026 ACM Student Chapter, Banasthali Vidyapith</small></footer>}
function GraphVisual(){return <div className="graph-visual"><svg viewBox="0 0 420 270"><path d="M210 38L105 112M210 38l105 74M105 112l-58 82m58-82 57 82m48-82 58 82"/><circle cx="210" cy="38" r="25"/><circle cx="105" cy="112" r="25"/><circle cx="315" cy="112" r="25"/><circle cx="47" cy="194" r="25"/><circle cx="162" cy="194" r="25"/><circle cx="373" cy="194" r="25"/></svg><div className="graph-num n1">10</div><div className="graph-num n2">5</div><div className="graph-num n3">15</div><div className="graph-num n4">3</div><div className="graph-num n5">7</div><div className="graph-num n6">20</div><code>binary_search_tree</code></div>}
function PixelScene(){return <div className="pixel-scene" aria-hidden="true"><i className="pixel-cloud c1"/><i className="pixel-cloud c2"/><i className="pixel-cloud c3"/><div className="pixel-grid"/><div className="pixel-terminal"><span>&gt; acm_bv.connect()</span><b>ACM</b><small>BV · READY</small></div><span className="pixel-dot d1"/><span className="pixel-dot d2"/><span className="pixel-dot d3"/></div>}
function Stats(){return <section className="stats">{[['250+','Community Members'],['20+','Campus Sessions'],['8+','Technical Initiatives'],['1','ACM BV Community']].map(([n,l])=><div key={l}><b>{n}</b><span>{l}</span></div>)}</section>}
function Timeline({full=false}){const [filter,setFilter]=useState('All');const data=roadmap.filter(x=>filter==='All'||x.difficulty===filter);return <section className={'timeline '+(full?'timeline-full':'')}><div className="section-top">{full&&<><p className="eyebrow">CURRICULUM / 12 MODULES</p><h1>DSA ROADMAP</h1><p className="muted">A structured path from fundamentals to advanced problem solving.</p><div className="roadmap-meta"><div><span>OVERALL PROGRESS</span><b>38%</b><Progress value={38}/></div><div><span>ESTIMATED JOURNEY</span><b>10–14 weeks</b></div></div><div className="filters">{['All','Beginner','Intermediate','Advanced'].map(f=><button className={f===filter?'selected':''} onClick={()=>setFilter(f)} key={f}>{f}</button>)}</div></>} {!full&&<><p className="eyebrow">THE CURRICULUM</p><h2>YOUR DSA JOURNEY</h2><p className="muted">From your first array to advanced algorithms.</p></>}</div><div className="timeline-list">{data.map((item,i)=><article className={'roadmap-card '+(item.progress===100?'done':'')+(item.progress>0&&item.progress<100?' current':'')} key={item.id}><div className="timeline-node">{item.progress===100?'✓':item.progress?'◉':'⌾'}</div><span className="step mono">{item.number}</span><div className="roadmap-content"><div><span className="pill">{item.difficulty}</span><h3>{item.title}</h3><p>{item.description}</p></div><div className="roadmap-side"><span className="mono">{item.lessons} LESSONS</span><Progress value={item.progress}/><b>{item.progress}%</b><Button onClick={()=>go('/learn/'+(topicInfo[item.id]?item.id:'arrays'))}>{item.progress?'Continue':'Explore'}</Button></div></div></article>)}</div></section>}
function Home(){return <><main className="hero"><PixelScene/><RippleGrid className="hero-ripple-grid"/><div className="hero-copy"><p className="eyebrow">ACM STUDENT CHAPTER · BANASTHALI VIDYAPITH</p><h1>WHERE CURIOUS<br/>MINDS <span>BUILD<br/>TOGETHER.</span></h1><p className="lead">ACM BV is a student-led technical community for people who want to learn openly, create with purpose, and grow alongside ambitious peers.</p><div className="actions"><Button onClick={()=>go('/register')}>Join ACM BV</Button></div></div></main><Stats/><ClubGallery/><section className="why"><p className="eyebrow">OUR COMMUNITY</p><h2>MORE THAN A CLUB.<br/>A PLACE TO BUILD.</h2><div className="feature-grid">{[['◈','Learning Circles','Learn new technologies together through student-led sessions.'],['⌘','Hands-on Workshops','Move from curiosity to confidence by making things.'],['↗','Hackathons & Challenges','Collaborate, experiment, and turn ideas into impact.'],['▣','Projects & Open Source','Build a portfolio of work that matters beyond the classroom.'],['◌','Peer Community','Meet people who will challenge, support, and inspire you.']].map(x=><article key={x[1]}><i>{x[0]}</i><h3>{x[1]}</h3><p>{x[2]}</p></article>)}</div></section><section className="everywhere"><p className="eyebrow">WHAT’S HAPPENING AT ACM BV</p><h2>FIND YOUR PLACE IN THE COMMUNITY</h2><div>{[['Tech talks','Ideas from students and industry'],['Build sessions','Make, test, and share together'],['DSA sessions','Strengthen your problem-solving foundation'],['Hackathon teams','Find collaborators for your next idea'],['Open-source circles','Contribute to projects that help others'],['Community events','Connect beyond the classroom']].map(([a,b])=><article key={a}><span>◇</span><b>{a}</b><small>→ {b}</small></article>)}</div></section><EventTimeline/><section className="acm-callout"><p className="eyebrow">ACM STUDENT CHAPTER · BV</p><h2>COME FOR THE<br/>CURIOSITY. STAY FOR<br/>THE COMMUNITY.</h2><p>Find your people, build your skills, and create the work you want to see.</p><Button onClick={()=>go('/register')}>Become a member</Button></section></>}
function ClubGallery(){return <section className="club-gallery"><div className="gallery-copy"><p className="eyebrow">CAMPUS · COMMUNITY · CODE</p><h2>LEARN TOGETHER.<br/>BUILD TOGETHER.</h2><p>ACM BV sessions turn technical ideas into practical confidence — from a student's first array to a team challenge on the lab floor.</p><Button kind="ghost" onClick={()=>go('/events')}>Explore club moments</Button></div><div className="photo-deck" aria-label="ACM BV event photo gallery"><article className="photo-card photo-session"><span>DSA SESSION 01</span><small>Hands-on learning</small></article><article className="photo-card photo-community"><span>ACM BV COMMUNITY</span><small>Meet the makers</small></article><article className="photo-card photo-talk"><span>INTERACTIVE TALKS</span><small>Share · ask · build</small></article></div></section>}
function OrbitalTimeline(){const [selected,setSelected]=useState(0);const events=[['AUG','Arrays & Strings','Begin your DSA series with foundations and problem patterns.'],['SEP','Linked Lists','Learn node-based thinking through an interactive lab.'],['OCT','Stack & Queue','Build LIFO/FIFO intuition with real code exercises.'],['NOV','Trees & Graphs','Explore connected structures and their applications.'],['DEC','Dynamic Programming','Close the year with a strategy-driven challenge.']];return <section className="orbital"><div className="orbit-copy"><p className="eyebrow">EVENT TIMELINE · 2026</p><h2>YOUR ACM BV<br/>LEARNING ORBIT</h2><p>{events[selected][2]}</p><Button onClick={()=>go('/learn/'+(['arrays','linked-list','stack','trees','dynamic-programming'][selected]))}>Open resource</Button></div><div className="orbit-stage"><div className="orbit-ring"/ ><div className="orbit-core"><b>ACM</b><span>BV</span></div>{events.map(([month,title],i)=>{let a=(i*72-90)*Math.PI/180;return <button key={month} className={'orbit-node '+(selected===i?'active':'')} style={{'--x':`${50+43*Math.cos(a)}%`,'--y':`${50+43*Math.sin(a)}%`}} onClick={()=>setSelected(i)}><b>{month}</b><span>{title}</span></button>})}</div></section>}
function Events(){return <main className="page events-page"><p className="eyebrow">ACM BV · ON CAMPUS</p><h1>LEARN IN THE ROOM.<br/>GROW IN THE COMMUNITY.</h1><p className="lead">Explore a DSA journey designed around sessions, collaborative practice, and the ACM BV community.</p><ClubGallery/><OrbitalTimeline/><section className="event-cta"><p className="eyebrow">READY FOR THE NEXT SESSION?</p><h2>BRING YOUR CURIOSITY.<br/>WE’LL BUILD THE REST.</h2><Button onClick={()=>go('/register')}>Register with ACM BV</Button></section></main>}
function Registration(){const [submitted,setSubmitted]=useState(false);const submit=e=>{e.preventDefault();setSubmitted(true)};return <main className="page register-page"><div className="register-intro"><p className="eyebrow">ACM BV STUDENT COMMUNITY</p><h1>YOUR NEXT<br/>CHAPTER STARTS<br/>HERE.</h1><p className="lead">Register your interest to receive DSA session updates, practice resources, and ACM BV community opportunities.</p><div className="registration-perks"><span>◈ DSA sessions & resources</span><span>◈ Community challenges</span><span>◈ Event updates</span></div></div><section className="registration-card">{submitted?<div className="registered"><i>✓</i><p className="eyebrow">REGISTRATION RECEIVED</p><h2>WELCOME TO THE JOURNEY.</h2><p>Thanks for registering your interest. The ACM BV team will share the next steps and upcoming session details with you.</p><Button onClick={()=>go('/')}>Back to home</Button></div>:<form onSubmit={submit}><p className="eyebrow">MEMBER REGISTRATION</p><h2>JOIN ACM BV DSA</h2><p className="muted">This frontend form is ready to connect to your future registration backend.</p><label>Full name<input required placeholder="Your name"/></label><label>College email<input required type="email" placeholder="you@banasthali.in"/></label><label>Programme / year<input required placeholder="e.g. BCA · Year 2"/></label><label>What would you like to explore?<select defaultValue=""><option value="" disabled>Select a focus area</option><option>DSA fundamentals</option><option>Competitive programming</option><option>Web development</option><option>Community events</option></select></label><label className="check"><input type="checkbox" required/> <span>I’d like to receive ACM BV event and learning updates.</span></label><button className="btn" type="submit">Register interest <span>→</span></button></form>}</section></main>}
function Challenge(){return <section className="challenge"><div><p className="eyebrow">DAILY DSA CHALLENGE</p><span className="challenge-day mono">DAY 19</span><h2>Maximum Subarray</h2><p>Find the contiguous subarray with the largest sum.</p><span className="pill medium">Medium</span> <b className="xp">+40 XP</b><br/><Button onClick={()=>go('/practice')}>Attempt Challenge</Button></div><div className="streak"><span>🔥</span><b>7 DAY<br/>STREAK</b><small>Keep your momentum going.</small></div></section>}
function Everywhere(){let d=[['Google Maps','Graph algorithms'],['Search engines','Trees, graphs, hashing'],['Social networks','Graphs'],['Databases','Trees and hashing'],['Operating systems','Queues and scheduling'],['E-commerce','Searching, sorting and recommendations']];return <section className="everywhere"><p className="eyebrow">REAL-WORLD APPLICATIONS</p><h2>DSA IS EVERYWHERE</h2><div>{d.map(([a,b])=><article key={a}><span>◇</span><b>{a}</b><small>→ {b}</small></article>)}</div></section>}
function EventTimeline(){const sessions=[['AUG 24','DSA Session 02','Arrays & problem-solving patterns','arrays'],['AUG 31','DSA Reconnect','Open practice lab & doubt clearing','arrays'],['SEP 07','DSA Session 03','Linked lists and pointer thinking','linked-list'],['SEP 14','DSA Challenge Day','Team-based coding challenge','stack'],['SEP 21','DSA Session 04','Stacks, queues & real-world use cases','stack']];return <section className="event-timeline upcoming-events"><p className="eyebrow">ACM BV × DSA SESSIONS</p><h2>UPCOMING EVENTS</h2><p className="muted">Save the dates — join the next hands-on DSA sessions with ACM BV.</p><div>{sessions.map(([date,title,detail,id])=><button key={date} onClick={()=>go('/learn/'+id)}><b>{date}</b><span><i>UPCOMING</i>{title}</span><small>{detail}</small></button>)}</div></section>}
function CodeBlock(){const [lang,setLang]=useState('Java');const code={Java:'int[] arr = {10, 20, 30, 40};\n\nfor (int i = 0; i < arr.length; i++) {\n  System.out.println(arr[i]);\n}','C++':'vector<int> arr = {10, 20, 30, 40};\n\nfor (int value : arr) {\n  cout << value << endl;\n}',Python:'arr = [10, 20, 30, 40]\n\nfor value in arr:\n    print(value)'};return <section className="code-section"><div className="code-head"><div>{Object.keys(code).map(x=><button className={x===lang?'selected':''} onClick={()=>setLang(x)} key={x}>{x}</button>)}</div><button onClick={()=>navigator.clipboard?.writeText(code[lang])}>⧉ Copy</button></div><pre><code>{code[lang]}</code></pre></section>}
function ArrayLab(){const [arr,setArr]=useState([10,25,7,42,18]),[val,setVal]=useState(''),[selected,setSelected]=useState(null),[message,setMessage]=useState('Select an element to inspect it.');const mutate=(fn,msg)=>{setArr(fn);setMessage(msg);setSelected(null)};return <div className="lab"><div className="array-row">{arr.map((x,i)=><button className={selected===i?'chosen':''} onClick={()=>{setSelected(i);setMessage(`Index ${i} contains ${x}. Access is O(1).`)}} key={i}><b>{x}</b><small>{i}</small></button>)}</div><div className="controls"><input value={val} onChange={e=>setVal(e.target.value)} placeholder="Value" type="number"/><Button onClick={()=>{let n=Number(val);let index=arr.indexOf(n);setSelected(index);setMessage(index>-1?`${n} found at index ${index}. Search took up to O(n).`:`${n} is not in the array.`)}}>Search</Button><Button kind="ghost" onClick={()=>mutate(a=>[...a,Number(val||0)],`Inserted ${val||0} at the end.`)}>Insert</Button><Button kind="ghost" onClick={()=>selected!==null&&mutate(a=>a.filter((_,i)=>i!==selected),`Deleted index ${selected}.`)}>Delete</Button><button className="link-btn" onClick={()=>{setArr([10,25,7,42,18]);setMessage('Array reset.');setSelected(null)}}>Reset</button></div><p className="lab-message">{message}</p></div>}
function Quiz(){const [ans,setAns]=useState(null);let q=['O(1)','O(n)','O(log n)','O(n²)'];return <section className="quiz"><p className="eyebrow">KNOWLEDGE CHECK</p><h2>CHECK YOUR UNDERSTANDING</h2><p>What is the time complexity of accessing an array element by index?</p><div>{q.map((x,i)=><button key={x} className={ans===i?(i===0?'correct':'wrong'):''} onClick={()=>setAns(i)}>{x}</button>)}</div>{ans!==null&&<p className={ans===0?'success':'error'}>{ans===0?'Correct — an index calculates an element’s location directly.':'Not quite. Arrays give direct access by index, so it is O(1).'}</p>}</section>}
function TopicPage({id}){let t=topicInfo[id]||topicInfo.arrays;return <main className="topic-page"><a className="back" onClick={()=>go('/roadmap')}>← Back to roadmap</a><p className="eyebrow">LEARNING MODULE</p><h1>{t.title.toUpperCase()}</h1><p className="lead">{t.blurb}</p><div className="topic-stats"><div><span>DIFFICULTY</span><b>{t.difficulty}</b></div><div><span>ESTIMATED TIME</span><b>{t.time}</b></div><div><span>PROGRESS</span><b>{t.progress}%</b><Progress value={t.progress}/></div></div><section className="lesson-copy"><div><h2>What is it?</h2><p>{t.what}</p></div><div><h2>Why does it matter?</h2><p>{t.why}</p></div><div><h2>Real-world examples</h2><ul>{t.examples.map(x=><li key={x}>{x}</li>)}</ul></div></section>{id==='arrays'&&<section><h2>INTERACTIVE ARRAY</h2><p className="muted">Click a value to access it, then try an operation.</p><ArrayLab/></section>}<section><h2>COMPLEXITY AT A GLANCE</h2><table><thead><tr><th>Operation</th><th>Average</th><th>Worst</th></tr></thead><tbody>{[['Access','O(1)','O(1)'],['Search','O(n)','O(n)'],['Insert','O(n)','O(n)'],['Delete','O(n)','O(n)']].map(r=><tr key={r[0]}>{r.map(x=><td key={x} className="mono">{x}</td>)}</tr>)}</tbody></table></section><section><h2>CODE EXAMPLE</h2><CodeBlock/></section><Quiz/></main>}
function Practice(){const [difficulty,setDifficulty]=useState('All'),[status,setStatus]=useState('All'),[topic,setTopic]=useState('All');let list=problems.filter(p=>(difficulty==='All'||p.difficulty===difficulty)&&(status==='All'||(status==='Solved')===p.solved)&&(topic==='All'||p.topic===topic));return <main className="page"><p className="eyebrow">BUILD FLUENCY</p><h1>PRACTICE ARENA</h1><p className="lead">Turn concepts into problem-solving skills.</p><div className="filters selects">{[['Topic',topic,setTopic,['All','Arrays','Stack','Linked Lists','Trees','Graphs','Dynamic Programming']],['Difficulty',difficulty,setDifficulty,['All','Easy','Medium','Hard']],['Status',status,setStatus,['All','Solved','Unsolved']]].map(([l,v,set,opts])=><label key={l}>{l}<select value={v} onChange={e=>set(e.target.value)}>{opts.map(x=><option key={x}>{x}</option>)}</select></label>)}</div><div className="problem-grid">{list.map(p=><article className="problem" key={p.title}><div><span className={'pill '+p.difficulty.toLowerCase()}>{p.difficulty}</span>{p.solved&&<span className="solved">✓ Solved</span>}</div><h3>{p.title}</h3><p>{p.topic}</p><footer><span>⚡ +{p.xp} XP</span><small>{p.count} solved</small></footer><Button>Open problem</Button></article>)}</div></main>}
function StackLab({type='stack'}){const [values,setValues]=useState(type==='queue'?[10,20,30]:[10,20,30]),[input,setInput]=useState(''),[note,setNote]=useState('Ready.');let isQueue=type==='queue';let add=()=>{if(input){setValues(v=>[...v,Number(input)]);setNote(`${input} ${isQueue?'enqueued':'pushed'}.`);setInput('')}};let remove=()=>{let x=isQueue?values[0]:values.at(-1);setValues(v=>isQueue?v.slice(1):v.slice(0,-1));setNote(x===undefined?'Structure is empty.':`${x} ${isQueue?'dequeued':'popped'}.`)};return <div className="lab stack-lab"><div className={'stack-box '+(isQueue?'queue-box':'')}>{values.map((v,i)=><div key={i}>{v}</div>)}</div><p className="mono">{isQueue?'FRONT ← FIRST IN, FIRST OUT ← REAR':'TOP · LAST IN, FIRST OUT'}</p><div className="controls"><input type="number" value={input} onChange={e=>setInput(e.target.value)} placeholder="Enter value"/><Button onClick={add}>{isQueue?'Enqueue':'Push'}</Button><Button kind="ghost" onClick={remove}>{isQueue?'Dequeue':'Pop'}</Button><Button kind="ghost" onClick={()=>setNote(`${isQueue?'Front':'Top'}: ${isQueue?values[0]:values.at(-1)??'empty'}`)}>Peek</Button><button className="link-btn" onClick={()=>{setValues([10,20,30]);setNote('Reset.')}}>Reset</button></div><p className="lab-message">{note} {isQueue?'Enqueue, dequeue and peek are O(1).':'Push, pop and peek are O(1).'}</p></div>}
function SortLab(){const [a,setA]=useState([42,17,31,8,25]);const sort=()=>{let b=[...a],steps=[];for(let i=0;i<b.length;i++)for(let j=0;j<b.length-i-1;j++)if(b[j]>b[j+1]){[b[j],b[j+1]]=[b[j+1],b[j]];steps.push([...b])}steps.forEach((x,i)=>setTimeout(()=>setA(x),i*220))};return <div className="lab"><div className="bars">{a.map(x=><div key={x} style={{height:x*3}}><span>{x}</span></div>)}</div><Button onClick={sort}>Animate Bubble Sort</Button><button className="link-btn" onClick={()=>setA([42,17,31,8,25])}>Reset</button><p className="lab-message">Compare adjacent values and swap them when they are out of order. Worst case: O(n²).</p></div>}
function BinaryLab(){const arr=[4,9,13,18,23,31,37,44,52];const [target,setTarget]=useState(31),[visited,setVisited]=useState([]),[note,setNote]=useState('Choose a target, then start searching.');const run=()=>{let lo=0,hi=arr.length-1,steps=[];while(lo<=hi){let mid=Math.floor((lo+hi)/2);steps.push(mid);if(arr[mid]===target)break;if(arr[mid]<target)lo=mid+1;else hi=mid-1}steps.forEach((x,i)=>setTimeout(()=>{setVisited(s=>[...s,x]);if(arr[x]===target)setNote(`Found ${target} at index ${x} in ${i+1} steps.`)},i*500))};return <div className="lab"><div className="array-row binary-row">{arr.map((x,i)=><div key={x} className={visited.includes(i)?(x===target?'found':'checked'):''}>{x}</div>)}</div><div className="controls"><select value={target} onChange={e=>{setTarget(Number(e.target.value));setVisited([])}}>{arr.map(x=><option key={x}>{x}</option>)}</select><Button onClick={()=>{setVisited([]);setTimeout(run,50)}}>Start search</Button><button className="link-btn" onClick={()=>{setVisited([]);setNote('Search reset.')}}>Reset</button></div><p className="lab-message">{note} Binary search runs in O(log n) on sorted data.</p></div>}
